    function insertCss(css) {
      if (stylesLib && typeof stylesLib.insert === 'function') {
        return stylesLib.insert(css)
      }
      try {
        var el = document.createElement('style')
        el.setAttribute('data-dsh-free-pane', '')
        el.textContent = css
        document.head.appendChild(el)
        return function () {
          if (el.parentNode) el.parentNode.removeChild(el)
        }
      } catch (e) {
        return function () {}
      }
    }

    var TREE_KEY = 'dsh-free-pane.tree.v1'
    var CANVAS_ADD = [
      { kind: 'session', label: '会话' },
      { kind: 'note', label: '笔记（Markdown）' },
      { kind: 'browser', label: '浏览器' },
    ]
    // 用户级默认缩放：75 / 100 / 125。新卡继承，顶栏改一次会同步已有 frame 卡。
    var ZOOM_PREF = (function () {
      try {
        var v = Number(localStorage.getItem('dsh-free-pane.zoom'))
        return [0.75, 1, 1.25].indexOf(v) >= 0 ? v : 0.75
      } catch (eZP) { return 0.75 }
    })()
    function isFrameKind(k) {
      return k === 'session' || k === 'panel' || k === 'browser' || k === 'web'
    }

    var CANVAS_LABEL = {
      empty: '填空窗格', session: '会话卡片', web: '网页卡片', note: '笔记卡片', region: '抓取卡片',
      terminal: '终端卡片', files: '文件卡片', git: 'Git 卡片', browser: '浏览器卡片', panel: '面板卡片', dash: '仪表卡片', std: '标准窗口',
      usage: '用量卡片', ocr: 'OCR 卡片', api: '插件卡片', ctx: '看板卡片', settings: '设置卡片',
    }

    // —— 宿主侧的两件小东西：浮条（带撤销）与自绘输入框 ——
    // 它们跟画布在不在屏上无关，所以留在模块层；都直接操作 DOM，不参与 React 渲染。
    var PANE_LABEL = '自由窗格'
    var TOAST_MS = 12000

    // 复制失败时的兜底：把 CSS 摆进一个可全选、可手动复制的对话框。
    function fpCssDialog(text) {
      var wrap = document.createElement('div')
      wrap.className = 'fp-veil'
      wrap.setAttribute('role', 'dialog')
      wrap.setAttribute('aria-modal', 'true')
      applyThemeVars(wrap, LIVE_THEME_DARK)
      var box = document.createElement('div')
      box.className = 'fp-prompt is-css'
      var q = document.createElement('div')
      q.className = 'fp-prompt-q'
      q.textContent = '这组尺寸的 CSS'
      var ta = document.createElement('textarea')
      ta.className = 'fp-css-out'
      ta.readOnly = true
      ta.spellcheck = false
      ta.value = String(text || '')
      var row = document.createElement('div')
      row.className = 'fp-prompt-row'
      var closeBtn = document.createElement('button')
      closeBtn.type = 'button'
      closeBtn.className = 'is-ok'
      closeBtn.textContent = '关闭'
      row.appendChild(closeBtn)
      box.appendChild(q)
      box.appendChild(ta)
      box.appendChild(row)
      wrap.appendChild(box)
      function done() { try { if (wrap.parentNode) wrap.parentNode.removeChild(wrap) } catch (eRm) {} }
      closeBtn.addEventListener('click', done)
      wrap.addEventListener('click', function (ev) { if (ev.target === wrap) done() })
      wrap.addEventListener('keydown', function (ev) { if (ev.key === 'Escape') { ev.preventDefault(); done() } })
      document.body.appendChild(wrap)
      try { ta.focus(); ta.select() } catch (eSel) {}
      return wrap
    }

    // 通用只读文本框：诊断内容太长，prompt() 在某些 Electron 版本里会卡住，
    // 这里用页面内对话框，内容默认全选，Ctrl+C 即可。
    function fpTextDialog(title, text) {
      var wrap = document.createElement('div')
      wrap.className = 'fp-veil'
      wrap.setAttribute('role', 'dialog')
      wrap.setAttribute('aria-modal', 'true')
      applyThemeVars(wrap, LIVE_THEME_DARK)
      var box = document.createElement('div')
      box.className = 'fp-prompt is-css'
      var q = document.createElement('div')
      q.className = 'fp-prompt-q'
      q.textContent = String(title || '复制')
      var ta = document.createElement('textarea')
      ta.className = 'fp-css-out'
      ta.readOnly = true
      ta.spellcheck = false
      ta.value = String(text || '')
      var row = document.createElement('div')
      row.className = 'fp-prompt-row'
      var copyBtn = document.createElement('button')
      copyBtn.type = 'button'
      copyBtn.className = 'is-ok'
      copyBtn.textContent = '复制'
      var closeBtn = document.createElement('button')
      closeBtn.type = 'button'
      closeBtn.textContent = '关闭'
      row.appendChild(closeBtn)
      row.appendChild(copyBtn)
      box.appendChild(q)
      box.appendChild(ta)
      box.appendChild(row)
      wrap.appendChild(box)
      function done() { try { if (wrap.parentNode) wrap.parentNode.removeChild(wrap) } catch (eRm) {} }
      function copyNow() {
        try { ta.focus(); ta.select() } catch (eSel) {}
        try { document.execCommand('copy') } catch (eCopy) {}
        copyBtn.textContent = '已复制'
        window.setTimeout(function () { copyBtn.textContent = '复制' }, 1600)
      }
      copyBtn.addEventListener('click', copyNow)
      closeBtn.addEventListener('click', done)
      wrap.addEventListener('click', function (ev) { if (ev.target === wrap) done() })
      wrap.addEventListener('keydown', function (ev) { if (ev.key === 'Escape') { ev.preventDefault(); done() } })
      document.body.appendChild(wrap)
      try { ta.focus(); ta.select() } catch (eSel2) {}
      return wrap
    }

    function fpToast(opts) {
      var o = opts || {}
      var host = null
      try { host = document.body } catch (eBody) { host = null }
      if (!host) return null
      var el = document.createElement('div')
      el.className = 'fp-portal'
      el.setAttribute('role', 'status')
      applyThemeVars(el, LIVE_THEME_DARK)
      var text = document.createElement('div')
      text.className = 'fp-toast-text'
      text.textContent = String(o.text || '')
      el.appendChild(text)
      var timer = null
      function close() {
        if (timer) { window.clearTimeout(timer); timer = null }
        try { if (el.parentNode) el.parentNode.removeChild(el) } catch (eRm) {}
      }
      if (o.action) {
        var act = document.createElement('button')
        act.type = 'button'
        act.className = 'fp-toast-btn'
        act.textContent = String(o.action)
        act.addEventListener('click', function () {
          trace('toast-action', { label: String(o.action) })
          close()
          try { if (typeof o.onAction === 'function') o.onAction() } catch (eAct) {}
        })
        el.appendChild(act)
      }
      var x = document.createElement('button')
      x.type = 'button'
      x.className = 'fp-toast-x'
      x.title = '关掉'
      x.setAttribute('aria-label', '关掉')
      x.appendChild(fpIconEl('close', 18))
      x.addEventListener('click', close)
      el.appendChild(x)
      host.appendChild(el)
      if (TOAST_MS > 0) timer = window.setTimeout(close, Number(o.ms || TOAST_MS))
      return { close: close, el: el }
    }

    // 宿主桌面版里 window.prompt 会被吞（Electron 默认不开），改卡片名不能靠它。
    function fpPrompt(opts) {
      var o = opts || {}
      var wrap = document.createElement('div')
      wrap.className = 'fp-veil'
      wrap.setAttribute('role', 'dialog')
      wrap.setAttribute('aria-modal', 'true')
      applyThemeVars(wrap, LIVE_THEME_DARK)
      var box = document.createElement('div')
      box.className = 'fp-prompt'
      var q = document.createElement('div')
      q.className = 'fp-prompt-q'
      q.textContent = String(o.text || '')
      var input = document.createElement('input')
      input.type = 'text'
      input.value = String(o.value == null ? '' : o.value)
      input.placeholder = String(o.placeholder || '')
      var row = document.createElement('div')
      row.className = 'fp-prompt-row'
      var cancel = document.createElement('button')
      cancel.type = 'button'
      cancel.textContent = '取消'
      var ok = document.createElement('button')
      ok.type = 'button'
      ok.className = 'is-ok'
      ok.textContent = String(o.okText || '确定')
      row.appendChild(cancel)
      row.appendChild(ok)
      box.appendChild(q)
      box.appendChild(input)
      box.appendChild(row)
      wrap.appendChild(box)
      function done(value) {
        try { if (wrap.parentNode) wrap.parentNode.removeChild(wrap) } catch (eRm) {}
        if (typeof o.onDone === 'function') o.onDone(value)
      }
      ok.addEventListener('click', function () { done(input.value) })
      cancel.addEventListener('click', function () { done(null) })
      wrap.addEventListener('keydown', function (ev) {
        if (ev.key === 'Enter') { ev.preventDefault(); done(input.value) }
        if (ev.key === 'Escape') { ev.preventDefault(); done(null) }
      })
      wrap.addEventListener('click', function (ev) { if (ev.target === wrap) done(null) })
      document.body.appendChild(wrap)
      window.setTimeout(function () { try { input.focus(); input.select() } catch (eF) {} }, 30)
      return wrap
    }

    // 会话 id 的两种写法（带或不带 session- 前缀）在这里统一掉：dsh-context 只认裸 uuid。
    function fpSidKey(sid) {
      return String(sid || '').replace(/^session-/, '')
    }

    // 卡片里的副本可能跑在**另一个代理端口**上（一张卡一个 origin，避免同源连接被吃满），
    // 这时候父页面读不到它的 contentDocument。副本自己进了对话就 postMessage 报一声，
    // 父页面据此把「还没打开这场对话」的兜底条撤掉——跨 origin 也能用。
    function installFrameReadyBridge() {
      if (window.__fpReadyBridge) return
      window.__fpReadyBridge = 1
      window.__fpReadySids = window.__fpReadySids || {}
      window.addEventListener('message', function (ev) {
        var d = ev && ev.data
        if (!d || d.__fp !== 'ready') return
        var k = fpSidKey(d.sid)
        if (!k) return
        window.__fpReadySids[k] = Date.now()
      })
    }

    function paneLabelPattern() {      return new RegExp(PANE_LABEL + '|Free Pane|自由窗格', 'i')
    }

    // 侧栏「取消固定」一点就删、没有回头路（压测 P1-11）。宿主的固定状态只存在内存里、
    // 没有对外的写入接口；实测重新钉回去的入口是「更多 → 编辑侧栏…」里那个勾选框，
    // 所以撤销就是替用户走一遍：开菜单 → 编辑侧栏 → 勾上自己 → 完成。
    function repinPane() {
      var nav = null
      try { nav = document.querySelector('nav[aria-label]') } catch (eNav) { nav = null }
      var more = nav ? nav.querySelector('button[aria-haspopup="menu"]') : null
      if (!more) {
        try { more = document.querySelector('button[aria-haspopup="menu"]') } catch (eMore) { more = null }
      }
      if (!more) {
        fpToast({ text: '没找到侧栏的「更多」菜单，请手动到「更多 → 编辑侧栏…」里勾回「' + PANE_LABEL + '」' })
        return
      }
      try { more.click() } catch (eClick) {}
      var want = paneLabelPattern()
      var step = 0
      var tries = 0
      var timer = window.setInterval(function () {
        tries += 1
        try {
          if (step === 0) {
            // 第一步：菜单里的「编辑侧栏…」
            var items = document.querySelectorAll('[role="menuitem"],button')
            for (var i = 0; i < items.length; i += 1) {
              var txt = String(items[i].textContent || '').replace(/\s+/g, '')
              if (!/编辑侧栏/.test(txt)) continue
              items[i].click()
              step = 1
              tries = 0
              trace('repin-menu')
              break
            }
          } else if (step === 1) {
            // 第二步：弹层里「自由窗格」那一行的勾选框。文本可能挂在 label、
            // 兄弟节点或上层容器上，几种都看一眼。
            var boxes = document.querySelectorAll('input[type="checkbox"]')
            for (var b = 0; b < boxes.length; b += 1) {
              var box = boxes[b]
              // 只认「自己这一行的文字」：先 label，再看紧邻的兄弟、父层。
              // 别把整块列表容器的文本拼进来——那样每一项都会命中第一项。
              var cand = []
              try {
                var lb = box.closest('label')
                if (lb) cand.push(lb.textContent)
                if (box.nextElementSibling) cand.push(box.nextElementSibling.textContent)
                if (box.parentElement) cand.push(box.parentElement.textContent)
              } catch (eCand) {}
              var hit = ''
              for (var c = 0; c < cand.length; c += 1) {
                var ct = String(cand[c] || '').replace(/\s+/g, '')
                if (!ct || ct.length > 40) continue
                if (want.test(ct)) { hit = ct; break }
              }
              if (!hit) continue
              if (!box.checked) box.click()
              step = 2
              tries = 0
              window.clearInterval(timer)
              trace('repin-check', { checked: !!box.checked, lab: hit.slice(0, 20) })
              window.setTimeout(function () {
                try {
                  var btns = document.querySelectorAll('button')
                  for (var k = 0; k < btns.length; k += 1) {
                    if (/^完成$/.test(String(btns[k].textContent || '').trim())) { btns[k].click(); break }
                  }
                } catch (eDone) {}
                trace('unpin-undo', {})
                fpToast({ text: '已经把「' + PANE_LABEL + '」放回侧边栏' })
              }, 300)
              return
            }
          }
        } catch (eStep) {}
        if (tries > 26) {
          window.clearInterval(timer)
          trace('repin-fail', { step: step })
          fpToast({ text: '没能自动放回去，请在侧栏「更多 → 编辑侧栏…」里勾回「' + PANE_LABEL + '」' })
        }
      }, 140)
    }

    function installUnpinUndo() {
      if (window.__fpUnpinUndo) return
      window.__fpUnpinUndo = true
      var want = paneLabelPattern()
      document.addEventListener('click', function (ev) {
        var t = ev.target
        var btn = t && t.closest ? t.closest('button[aria-label]') : null
        if (!btn) return
        var lab = String(btn.getAttribute('aria-label') || '')
        if (!/取消固定|Unpin/i.test(lab)) return
        if (!want.test(lab)) return
        // 宿主自己会把它摘掉；等一帧再弹浮条，免得浮条跟着列表一起被 React 重排吞掉。
        trace('unpin-click', { label: lab })
        window.setTimeout(function () {
          fpToast({
            text: '已从侧边栏移除「' + PANE_LABEL + '」',
            action: '撤销',
            onAction: repinPane,
          })
        }, 80)
      }, true)
    }

    // 宿主界面里那些「自成一块」的东西（挂件、统计条、输入框、导轨……）各有自己的
    // 根节点，跟对话列是兄弟甚至挂在 body 上，所以可以单独抓成窗口，互不影响。
    var GRAB_PRESETS = [
      { id: 'whale', label: '小鲸鱼 / 余额', sel: '.dshwv-root' },
      { id: 'stats', label: '轮次 / 步数 / Token', sel: '[class*=dsh-claude-inline-stats]', live: true },
      { id: 'dock', label: '输入框底部整条（含量/余额/用量）', sel: '[data-dsh-claude-part="composer-dock"]', live: true },
      { id: 'cards', label: '用量卡片（环形图 + 明细）', sel: '[class*=lc-cols]', live: true },
      { id: 'talkmap', label: '对话地图（talk-map）', sel: '[class*="cardChip"]' },
      { id: 'worldcard', label: '世界 · 活动卡（world）', sel: '[class*="dw-card"],[class*="dw-bar"]' },
      { id: 'hubarea', label: '插件市场面板（plugin-hub）', sel: '[class*="dph-area"],[class*="dph-body"]' },
      { id: 'bibcard', label: '底部信息 · 卡片（bottom-info-bar）', sel: '[class*="bib-go-card"],[class*="bib-go"]' },
      { id: 'bottombar', label: '底部信息栏', sel: '[class*=bottomRow]' },
      { id: 'composer', label: '输入框', sel: '[class*=composerCard]' },
      { id: 'column', label: '对话列', sel: '[class*=column]' },
      { id: 'sidebar', label: '左侧栏', sel: '[class*=sidebarCol]' },
      { id: 'rightpanel', label: '右侧栏面板', sel: '[class*=panelBody]' },
    ]


