    // 这样「任何时候按 Alt+D 抓一块」都能成立，不管当前开的是哪个面板。
    var CAPTURE_HANDLERS = []
    var LAST_CAPTURE_AT = 0
    // 由 apply 里注册：把宿主主面板切回「自由画布」（抓完自动回去看结果）。
    var SHOW_CANVAS = null

