    function guessProxyAddress() {
      try {
        if (location.protocol !== 'http:' && location.protocol !== 'https:') return ''
        var h = String(location.hostname || '')
        if (h !== '127.0.0.1' && h !== 'localhost') return ''
        return location.origin + '/'
      } catch (e) {
        return ''
      }
    }

