    // 从 root 往下按子节点下标走：镜像与源的结构一一对应。
    function pathWithin(root, node) {
      var out = []
      var cur = node
      while (cur && cur !== root) {
        var parent = cur.parentNode
        if (!parent) return null
        var idx = -1
        for (var i = 0; i < parent.childNodes.length; i++) {
          if (parent.childNodes[i] === cur) { idx = i; break }
        }
        if (idx < 0) return null
        out.unshift(idx)
        cur = parent
      }
      return cur === root ? out : null
    }

    function nodeAtPath(root, path) {
      var cur = root
      if (!cur || !path) return null
      for (var i = 0; i < path.length; i++) {
        cur = cur.childNodes[path[i]]
        if (!cur) return null
      }
      return cur
    }

    // 会话 id 有两种写法：列表里带 "session-" 前缀，从侧栏拖出来的是裸 uuid。
    // 不归一化对不上号，标题和下拉框就会退回显示那串 uuid。
    function fullId(id) {
      var s = String(id || '')
      if (!s) return ''
      return s.indexOf('session-') === 0 ? s : 'session-' + s
    }

    // 宿主右栏文件面板认的地址：dsh-resource://file/absolute/<encoded path>。
    function fileResourceAddress(p) {
      var norm = String(p || '').replace(/\\/g, '/')
      var enc = norm.split('/').map(function (seg) {
        return encodeURIComponent(seg).replace(/%3A/gi, ':')
      }).join('/')
      return 'dsh-resource://file/absolute/' + enc
    }

    function baseName(p) {
      var s = String(p || '').replace(/[\\/]+$/, '')
      var i = Math.max(s.lastIndexOf('/'), s.lastIndexOf('\\'))
      return i >= 0 ? s.slice(i + 1) : s
    }

    // 卡片名字尽量「按内容取」：用户没改过名时，标题栏后面跟的那一段由这里决定。
    function canvasTitle(leaf) {      if (!leaf) return ''
      // 用户右键改过的名字优先：改名之后标题栏、拖拽预览、菜单头都用同一个名字。
      if (leaf.title) return String(leaf.title).slice(0, 40)
      if (leaf.kind === 'session') return leaf.sessionId ? String(leaf.sessionId).replace(/^session-/, '').slice(0, 8) : '未选'
      if (leaf.kind === 'web') return leaf.url ? String(leaf.url).replace(/^https?:\/\//, '').slice(0, 40) : '输入网址'
      if (leaf.kind === 'files') {
        if (leaf.fileActive) return String(leaf.fileActive).slice(-32)
        if (leaf.file) return String(leaf.file).slice(-32)
        return leaf.dir ? String(leaf.dir).slice(-28) : ''
      }
      if (leaf.kind === 'dash') return String(leaf.route || '未选路由').replace(/^https?:\/\//, '').slice(-32)
      if (leaf.kind === 'std') {
        var stdData = leaf.data || {}
        return String(stdData.title || (STD_LABEL[leaf.std] || '标准') + '窗口').slice(-32)
      }
      if (leaf.kind === 'git') return leaf.cwd ? String(leaf.cwd).slice(-28) : ''
      if (leaf.kind === 'note') {
        var t = String(leaf.text || '').replace(/\r/g, '').split('\n')[0] || ''
        t = t.replace(/^[#>\s\-*+]+/, '').replace(/\s+/g, ' ').trim()
        return t ? t.slice(0, 24) : '空白笔记'
      }
      if (leaf.kind === 'region') return String(leaf.label || '').slice(0, 20)
      if (leaf.kind === 'ctx') {
        var cm = String(leaf.ctxMode || 'tokens')
        return CTX_TITLES[cm] || '看板'
      }
      if (leaf.kind === 'context') return '上下文占用'
      if (leaf.kind === 'api') {
        var ap = String(leaf.path || '')
        if (!ap) return '插件接口'
        return ap.replace(/^https?:\/\/[^/]+/i, '').replace(/^\//, '').slice(0, 30) || '插件接口'
      }
      if (leaf.kind === 'terminal') return leaf.cwd ? baseName(leaf.cwd) : '终端'
      if (leaf.kind === 'ocr') return leaf.path ? baseName(leaf.path) : '本地 OCR'
      if (leaf.kind === 'browser') {
        var tabs = leaf.tabs || []
        var act = null
        for (var ti = 0; ti < tabs.length; ti += 1) if (tabs[ti] && tabs[ti].id === leaf.active) act = tabs[ti]
        var u = act && act.url ? String(act.url) : ''
        if (!u) return '浏览器'
        try { return (new URL(u)).hostname.replace(/^www\./, '').slice(0, 30) } catch (eUrl) { return u.slice(0, 30) }
      }
      if (leaf.kind === 'settings') return '设置'
      if (leaf.kind === 'empty') return '未选择'
      return ''
    }

    // 从一次拖放里判断"这是什么东西"
    // 底部工具条上那些「按钮」被拖到画布上时，由画布自己把它们解析成窗口内容。
    var TOOL_RESOLVER = null
    // 正在被加进画布的卡片叫什么名字：冻结遮罩上要写出来。
    var PENDING_LABEL = ''

    // 画布里的每一块叫「卡片」；卡片之间那条线叫「分割线」。
    function contentLabel(c) {
      if (!c) return '新卡片'
      var k = String(c.kind || '')
      if (k === 'session') return '会话卡片'
      if (k === 'note') return '笔记卡片'
      if (k === 'browser') return '浏览器卡片'
      if (k === 'web') return '网页卡片'
      if (k === 'region') return '仪表卡片'
      if (k === 'usage') return '用量卡片'
      if (k === 'api') return '插件卡片'
      if (k === 'ocr') return 'OCR 卡片'
      if (k === 'panel') return '面板卡片'
      if (k === 'files') return '文件卡片'
      if (k === 'git') return 'Git 卡片'
      if (k === 'terminal') return '终端卡片'
      if (k === 'empty') return '空卡片'
      if (k === 'ctx') return '看板卡片'
      if (k === 'context') return '上下文卡片'
      if (k === 'settings') return '设置卡片'
      return '新卡片'
    }

    // 文件路径取父目录；盘符根（C:）补成 C:\，否则 listDir 会读到「C 盘当前目录」。
    function dirOfPath(p) {
      var s0 = String(p || '')
      var ci = Math.max(s0.lastIndexOf('/'), s0.lastIndexOf('\\'))
      var cut = ci > 0 ? s0.slice(0, ci) : ''
      if (/^[a-zA-Z]:$/.test(cut)) cut += '\\'
      return cut
    }

    // 一个绝对路径拖进画布：文本类继续落成笔记（带 path），其余开一张「已经打开这个文件」的文件卡。
    function fileContentForPath(p) {
      var one = String(p || '')
      if (!one) return null
      var cut = dirOfPath(one)
      if (/\.(md|markdown|txt)$/i.test(one)) return { kind: 'note', text: '', path: one, dir: cut }
      return { kind: 'files', dir: cut, file: one, fileTabs: [one], fileActive: one }
    }

    function canvasDropContent(e) {
      var carried = DRAGGED
      var rawKind = ''
      try { rawKind = String(e.dataTransfer.getData('text/plain') || '') } catch (eRaw) {}
      // 文件卡里拖出来的行带了自己的 MIME：直接开成文件卡，不再当一段文字。
      var fpPath = ''
      try { fpPath = String(e.dataTransfer.getData('application/x-fp-path') || '') } catch (eFp) {}
      if (fpPath) return fileContentForPath(fpPath)
      if (rawKind.indexOf('fpkind:') === 0 && TOOL_RESOLVER) {
        var made = null
        try { made = TOOL_RESOLVER(rawKind.slice(7)) } catch (eMade) { made = null }
        if (made) return made
      }
      if (carried && carried.kind === 'session' && carried.value) {
        return { kind: 'session', sessionId: String(carried.value) }
      }
      if (carried && carried.kind === 'url' && carried.value) {
        return { kind: 'web', url: String(carried.value) }
      }
      if (carried && carried.kind === 'region' && carried.value) {
        return { kind: 'region', path: carried.value, label: carried.label || '片段' }
      }
      var files = null
      try { files = e.dataTransfer && e.dataTransfer.files } catch (err) {}
      if (files && files.length) {
        var p = String(files[0].path || '')
        var made2 = fileContentForPath(p)
        if (made2) return made2
      }
      var text = ''
      try { text = String(e.dataTransfer.getData('text/plain') || '') } catch (err2) {}
      if (!text.trim()) {
        try { text = String(e.dataTransfer.getData('text/uri-list') || '') } catch (err3) {}
      }
      if (!text.trim()) return null
      // 侧栏拖出来的会话行里放的是裸 uuid（不带 session- 前缀），
      // 以前只认带前缀的，于是被当成一段文字落成了笔记窗口。
      var sid = text.match(/(?:session-)?[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/i)
      if (sid) {
        var sidVal = sid[0]
        if (!/^session-/i.test(sidVal)) sidVal = 'session-' + sidVal
        return { kind: 'session', sessionId: sidVal }
      }
      var url = text.match(/https?:\/\/[^\s"'<>]+/i)
      if (url) return { kind: 'web', url: url[0] }
      return { kind: 'note', text: text }
    }

    var TRACE_LAST = ''
    // 诊断用：始终写日志，不受 fpTrace 门控（出错时才知道发生了什么）。
    function diag(name, extra) {
      try {
        fetch(RPC_BASE + '/log', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(Object.assign({ name: name, t: Date.now() }, extra || {})),
        }).catch(function () {})
      } catch (err) {}
    }

    function trace(name, extra) {
      try {
        // 嵌入副本的 URL 只有 fpEmbed，没有 fpTrace：把它也算作要日志，否则
        // 副本内部的探针（比如 panel-audit）永远进不了日志。
        if (!/[?&](fpTrace|fpDom|fpRow|fpEmbed)=/.test(String(window.location.search || ''))) return
        fetch(RPC_BASE + '/log', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(Object.assign({ name: name, t: Date.now() }, extra || {})),
        }).catch(function () {})
      } catch (err) {}
    }

    // 把窗口树摊平成「每片叶子一块绝对定位矩形」。
    // 好处：加窗、拖动、改比例时每个 CanvasLeaf 的 key 不变、位置只改 style，
    // iframe 不会被卸载重挂（否则每加一个窗口，其它窗的副本都要重新拉 20–30 秒）。
    function flatLayout(node, x, y, w, h, out) {
      if (!node) return
      if (node.type === 'leaf') {
        out.leaves.push({ leaf: node, x: x, y: y, w: w, h: h })
        return
      }
      var r = typeof node.ratio === 'number' ? node.ratio : 0.5
      if (r < 0.13) r = 0.13
      if (r > 0.87) r = 0.87
      if (node.dir === 'row') {
        var ax = w * r
        flatLayout(node.a, x, y, ax, h, out)
        flatLayout(node.b, x + ax, y, w - ax, h, out)
        out.dividers.push({ split: node, dir: 'row', x: x + ax, y: y, len: h })
      } else {
        var ay = h * r
        flatLayout(node.a, x, y, w, ay, out)
        flatLayout(node.b, x, y + ay, w, h - ay, out)
        // len = 这条缝自己那一段有多长：嵌套在某一分支里的分割线只画到分支边为止，
        // 否则就出现「T 型布局配十字线」那种溢出。
        out.dividers.push({ split: node, dir: 'col', x: x, y: y + ay, len: w })
      }
    }

    // —— 拖拽落点：只按指针位置算，不依赖指针下面压着哪个元素 ——
    //   between —— 指针贴在两张卡片之间的缝上：新卡片插到中间，两侧各让出一半；
    //   onto    —— 指针落在某张卡片里：四条边是「在这一侧劈开」，中间是「替换 / 填满这张卡片」。
    var DROP_SEAM_PX = 18
    var DROP_EDGE_BAND = 0.3

    // 把当前树算成像素矩形；缝（分隔线）也带上一段可命中的跨度。
    function flatDropGeometry(root, flatEl) {
      if (!root || !flatEl) return null
      var box = flatEl.getBoundingClientRect()
      if (!box.width || !box.height) return null
      var flat = { leaves: [], dividers: [] }
      flatLayout(root, 0, 0, 100, 100, flat)
      var leaves = flat.leaves.map(function (l) {
        return {
          id: l.leaf.id,
          leaf: l.leaf,
          x: box.left + (l.x / 100) * box.width,
          y: box.top + (l.y / 100) * box.height,
          w: (l.w / 100) * box.width,
          h: (l.h / 100) * box.height,
          pct: { x: l.x, y: l.y, w: l.w, h: l.h },
        }
      })
      var seams = flat.dividers.map(function (d) {
        if (d.dir === 'row') {
          return {
            splitId: d.split.id,
            dir: 'row',
            cx: box.left + (d.x / 100) * box.width,
            from: box.top + (d.y / 100) * box.height,
            to: box.top + ((d.y + d.len) / 100) * box.height,
            pct: { x: d.x, y: d.y, len: d.len },
          }
        }
        return {
          splitId: d.split.id,
          dir: 'col',
          cy: box.top + (d.y / 100) * box.height,
          from: box.left + (d.x / 100) * box.width,
          to: box.left + ((d.x + d.len) / 100) * box.width,
          pct: { x: d.x, y: d.y, len: d.len },
        }
      })
      return { box: box, leaves: leaves, seams: seams }
    }

    // 返回 { mode, label, pct }：pct 是相对 .fp-flat 的百分比，提示层直接照它画。
    function resolveDropTarget(geom, x, y, skipId, opts) {
      if (!geom) return null
      var o = opts || {}
      var band = typeof o.seamPx === 'number' ? o.seamPx : DROP_SEAM_PX
      // 1) 缝：指针贴着某条分隔线时，插到两张卡片之间（比卡片边缘优先）。
      var seam = null
      var seamDist = Infinity
      for (var i = 0; i < geom.seams.length; i += 1) {
        var s = geom.seams[i]
        var along = s.dir === 'row'
          ? (y >= s.from - band && y <= s.to + band)
          : (x >= s.from - band && x <= s.to + band)
        if (!along) continue
        var dist = s.dir === 'row' ? Math.abs(x - s.cx) : Math.abs(y - s.cy)
        if (dist > band) continue
        if (dist < seamDist) { seamDist = dist; seam = s }
      }
      if (seam) {
        var thick = 8
        var halfX = geom.box.width ? (thick / 2) / geom.box.width * 100 : 0.3
        var halfY = geom.box.height ? (thick / 2) / geom.box.height * 100 : 0.3
        var pct = seam.dir === 'row'
          ? { x: seam.pct.x - halfX, y: seam.pct.y, w: halfX * 2, h: seam.pct.len }
          : { x: seam.pct.x, y: seam.pct.y - halfY, w: seam.pct.len, h: halfY * 2 }
        return { mode: 'between', splitId: seam.splitId, dir: seam.dir, label: '插到这两张卡片之间', pct: pct }
      }
      // 2) 卡片：只认真正包含指针的那张（嵌套时取面积最小的内层）。
      var hit = null
      var area = Infinity
      for (var j = 0; j < geom.leaves.length; j += 1) {
        var l = geom.leaves[j]
        if (skipId && l.id === skipId) continue
        if (x < l.x || x > l.x + l.w || y < l.y || y > l.y + l.h) continue
        var a = l.w * l.h
        if (a < area) { area = a; hit = l }
      }
      if (!hit) return null
      var rx = hit.w ? (x - hit.x) / hit.w : 0.5
      var ry = hit.h ? (y - hit.y) / hit.h : 0.5
      var inX = rx >= DROP_EDGE_BAND && rx <= 1 - DROP_EDGE_BAND
      var inY = ry >= DROP_EDGE_BAND && ry <= 1 - DROP_EDGE_BAND
      var zone = 'center'
      if (!(inX && inY)) {
        var dl = rx
        var dr = 1 - rx
        var dt = ry
        var db = 1 - ry
        var m = Math.min(dl, dr, dt, db)
        zone = m === dl ? 'left' : (m === dr ? 'right' : (m === dt ? 'top' : 'bottom'))
      }
      if (zone === 'center' && o.noCenter) {
        // 内部搬卡片时「覆盖」会丢内容：中心区退化成最近的一条边。
        var dz = { left: rx, right: 1 - rx, top: ry, bottom: 1 - ry }
        var zk = 'left'
        var zv = Infinity
        for (var k in dz) { if (dz[k] < zv) { zv = dz[k]; zk = k } }
        zone = zk
      }
      var p = hit.pct
      var hint = { x: p.x, y: p.y, w: p.w, h: p.h }
      if (zone === 'left') hint.w = p.w * 0.5
      else if (zone === 'right') { hint.x = p.x + p.w * 0.5; hint.w = p.w * 0.5 }
      else if (zone === 'top') hint.h = p.h * 0.5
      else if (zone === 'bottom') { hint.y = p.y + p.h * 0.5; hint.h = p.h * 0.5 }
      var label = zone === 'left' ? '放进左边'
        : zone === 'right' ? '放进右边'
          : zone === 'top' ? '放进上方'
            : zone === 'bottom' ? '放进下方'
              : (hit.leaf && hit.leaf.kind === 'empty' ? '填入这张空卡片' : '替换这张卡片')
      return {
        mode: 'onto', leafId: hit.id, zone: zone, label: label, pct: hint,
        targetKind: hit.leaf && hit.leaf.kind,
      }
    }

    // 插到两张卡片之间：新卡片吃掉 f，左右两边各让出 f/2；不改谁比谁大，只从两边各切一点。
    function treeInsertBetween(node, splitId, content, fraction) {
      if (!node) return treeLeaf(content)
      if (node.type !== 'split') return node
      if (node.id === splitId) {
        var r = typeof node.ratio === 'number' ? node.ratio : 0.5
        var room = Math.min(r, 1 - r)
        var f = typeof fraction === 'number' && fraction > 0 ? fraction : 0.32
        f = Math.min(f, Math.max(0.12, room * 2 - 0.16), 0.5)
        var aShare = r - f / 2
        var bShare = (1 - r) - f / 2
        return {
          type: 'split', id: newId('s'), dir: node.dir, ratio: aShare,
          a: node.a,
          b: {
            type: 'split', id: newId('s'), dir: node.dir, ratio: f / (f + bShare),
            a: treeLeaf(content),
            b: node.b,
          },
        }
      }
      var na = treeInsertBetween(node.a, splitId, content, fraction)
      var nb = treeInsertBetween(node.b, splitId, content, fraction)
      if (na === node.a && nb === node.b) return node
      return { type: 'split', id: node.id, dir: node.dir, ratio: node.ratio, a: na, b: nb }
    }

    // 可以搜的标题下拉：原生 select 只能翻，场对话一多就找不动（压测报告 P1-10）。
    // 标题即下拉：这里只负责「按钮」，弹层由卡片根节点渲染（TitlePop）。
    // 以前弹层挂在按钮同级（.fp-head-title 里），标题栏是 flex + overflow，
    // 弹层被压成一条、还要靠 !important 硬顶宽度才勉强能用；现在它挂在
    // .fp-win 上、用内联 width:260px 定宽，跟标题栏怎么排布无关。
    function TitlePicker(props) {
      var curName = props.curId ? (props.titleOf(props.curId) || props.curId) : '自动（取左上方对话）'
      return h('div', { className: 'fp-tp' },
        h('button', {
          type: 'button',
          className: 'fp-tp-btn',
          ref: props.btnRef,
          title: curName + '｜点一下搜索、换这个卡片显示的对话',
          onPointerDown: function (e) { e.stopPropagation() },
          onClick: function (e) { e.preventDefault(); e.stopPropagation(); props.onToggle() },
        }, curName)
      )
    }

    // 弹层本体：挂在卡片根节点上，绝对定位到按钮下方，宽度内联写死 260px。
    function TitlePop(props) {
      var qHook = React.useState('')
      var q = qHook[0]
      var setQ = qHook[1]
      var rows = []
      ;(props.groups || []).forEach(function (g) {
        ;(g.rows || []).forEach(function (row) {
          rows.push({ id: String(row.id), name: props.titleOf(row.id) || row.name || row.id, group: g.name })
        })
      })
      // 同名会话在列表里必须能分辨：重名的补一段 id 尾巴。
      var nameCount = {}
      rows.forEach(function (r) { nameCount[r.name] = (nameCount[r.name] || 0) + 1 })
      rows.forEach(function (r) {
        if (nameCount[r.name] <= 1) return
        var tail = String(r.id).replace(/^session-/, '').slice(0, 6)
        // 名字里已经带了这段 id（「会话 9840efea」这类自动标题）就不再拼一遍。
        if (tail && String(r.name).toLowerCase().indexOf(tail.toLowerCase()) >= 0) return
        r.disp = r.name + ' · ' + tail
      })
      var needle = String(q || '').trim().toLowerCase()
      var hit = needle
        ? rows.filter(function (r) {
            return String(r.name).toLowerCase().indexOf(needle) >= 0 || String(r.id).toLowerCase().indexOf(needle) >= 0
          })
        : rows
      var shown = hit.slice(0, 40)
      return h('div', {
        className: 'fp-tp-pop',
        ref: props.popRef,
        style: {
          position: 'absolute',
          left: (props.pos ? props.pos.left : 6) + 'px',
          top: (props.pos ? props.pos.top : 34) + 'px',
          width: 260,
          maxWidth: 260,
        },
        onPointerDown: function (e) { e.stopPropagation() },
      }, [
        h('input', {
          key: 'q',
          className: 'fp-tp-input',
          autoFocus: true,
          placeholder: '搜对话名或 id…',
          value: q,
          onChange: function (e) { setQ(e.target.value) },
          onKeyDown: function (e) {
            if (e.key === 'Escape') { e.stopPropagation(); if (props.onClose) props.onClose() }
          },
        }),
        h('div', { key: 'l', className: 'fp-tp-list' },
          (shown.length ? shown : [{ id: '', name: needle ? '没有匹配的对话' : '还没有会话列表', group: '' }]).map(function (r, i) {
            return h('button', {
              key: r.id || 'none' + i,
              type: 'button',
              className: 'fp-tp-row' + (r.id && r.id === props.curId ? ' is-on' : ''),
              disabled: !r.id,
              onClick: function () { if (!r.id) return; if (props.onClose) props.onClose(); props.onPick(r.id) },
            }, (r.id ? ((r.id === props.curId ? '✓ ' : '') + (r.disp || r.name) + (r.group ? '  ·  ' + r.group : '')) : r.name))
          })
        ),
        hit.length > shown.length ? h('div', { key: 'm', className: 'fp-tp-more' }, '还有 ' + (hit.length - shown.length) + ' 条，输入更多字缩小范围') : null,
      ])
    }

