        tip.setAttribute('style', 'position:fixed;left:50%;transform:translateX(-50%);bottom:22px;padding:6px 14px;border-radius:999px;background:rgba(22,25,32,.94);color:#fff;font:12px/1.5 system-ui,sans-serif;box-shadow:0 8px 24px -10px rgba(0,0,0,.8);white-space:nowrap')
