    // 网页窗自带一条地址/搜索栏：认得出是网址就直接开，认不出当搜索词。
    // 底部工具条：把会话输入框下面那一排按钮「拔下来」，放在画布底部当窗口来源。
    var TOOL_BAR = [
      { id: 'capture', label: '相机', title: '从界面上取一块（截图）做成窗口' },
      { id: 'note', label: '笔记', title: '新建一个 Markdown 笔记窗口' },
      { id: 'ocr', label: 'OCR', title: '识别一张图里的字，结果写进下面的笔记' },
      { id: 'api', label: '插件', title: '读插件的接口 / 面板' },
      { id: 'context', label: '上下文', title: '这个对话的上下文占用（数字与官方同源）' },
      { id: 'usage', label: '用量', title: '轮次 / 步数 / Token' },
      { id: 'panel:terminal', label: '终端', title: '官方的终端' },
      { id: 'panel:files', label: '文件', title: '官方的文件树' },
    ]

    var ENGINES = [
      { id: 'bing', label: 'Bing', url: 'https://www.bing.com/search?q=' },
      { id: 'edge', label: 'Edge', url: 'https://www.bing.com/search?q=' },
      { id: 'google', label: 'Google', url: 'https://www.google.com/search?q=' },
      { id: 'baidu', label: '百度', url: 'https://www.baidu.com/s?wd=' },
    ]
