        note: 'Win11 三列：各 1/3',
        build: function (sid) {
          return presetSplit('row', 0.334, presetLeaf('files'),
            presetSplit('row', 0.5, presetLeaf('session', { sessionId: sid }), presetLeaf('note')))
        },
