        name: '瀑布四段',
        note: 'DeX 四分屏：上两窗、下一整条',
        build: function (sid) {
          return presetSplit('col', 0.58,
            presetSplit('row', 0.5, presetLeaf('session', { sessionId: sid }), presetLeaf('note')),
            presetSplit('row', 0.62, presetLeaf('files'), presetLeaf('usage')))
        },
